# ============================================================================
# FUNCTIONS
# ============================================================================

def review_data():
    """عرض ملخص البيانات المسحوبة"""
    print("=" * 60)
    print("  DATA REVIEW — Appwrite Cloud Backup")
    print("=" * 60)
    total = 0
    for col_id, col_data in BACKUP_DATA.items():
        count = col_data.get('total', 0)
        total += count
        docs = col_data.get('documents', [])
        if count > 0:
            # Show first doc keys as sample
            if docs:
                keys = [k for k in docs[0].keys() if not k.startswith('$')]
                print(f"\n  📦 {col_id} ({count} docs)")
                print(f"     Fields: {', '.join(keys[:10])}")
                if len(keys) > 10:
                    print(f"     ... and {len(keys) - 10} more fields")
        else:
            print(f"  📭 {col_id} (empty)")
    print(f"\n{'=' * 60}")
    print(f"  Total: {total} documents across {len(BACKUP_DATA)} collections")
    print(f"{'=' * 60}")


def export_json(filepath='appwrite_backup_export.json'):
    """تصدير البيانات كملف JSON"""
    with open(filepath, 'w', encoding='utf-8') as f:
        json.dump(BACKUP_DATA, f, ensure_ascii=False, indent=2, default=str)
    print(f"✅ Exported to {filepath}")


def export_per_collection(output_dir='appwrite_backup_collections'):
    """تصدير كل مجموعة في ملف منفصل"""
    import os
    os.makedirs(output_dir, exist_ok=True)
    for col_id, col_data in BACKUP_DATA.items():
        filepath = os.path.join(output_dir, f'{col_id}.json')
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(col_data.get('documents', []), f, ensure_ascii=False, indent=2, default=str)
        print(f"  ✅ {col_id}: {col_data.get('total', 0)} docs → {filepath}")
    print(f"\n✅ All collections exported to {output_dir}/")


def push_to_appwrite():
    """رفع البيانات إلى Appwrite Cloud — ⚠️ للتأهيل فقط"""
    if API_KEY == 'PLACE_YOUR_API_KEY_HERE':
        print("❌ ERROR: Set your API_KEY in the script first!")
        sys.exit(1)

    try:
        from appwrite.client import Client
        from appwrite.services.databases import Databases
    except ImportError:
        print("❌ ERROR: Install appwrite SDK first: pip install appwrite")
        sys.exit(1)

    client = Client()
    client.set_endpoint(ENDPOINT)
    client.set_project(PROJECT)
    client.set_key(API_KEY)
    db = Databases(client)

    print("⚠️  WARNING: This will UPSERT all documents to Appwrite Cloud!")
    print("⚠️  Press Ctrl+C to cancel, or Enter to continue...")
    input()

    for col_id, col_data in BACKUP_DATA.items():
        docs = col_data.get('documents', [])
        if not docs:
            print(f"  ⏭️  {col_id}: empty, skipping")
            continue

        print(f"  📤 {col_id}: pushing {len(docs)} docs...")
        success = 0
        errors = 0
        for doc in docs:
            doc_id = doc.get('$id', doc.get('localUuid', ''))
            if not doc_id:
                errors += 1
                continue
            # Remove system fields before upsert
            data = {k: v for k, v in doc.items() if not k.startswith('$')}
            try:
                db.update_document(DATABASE, col_id, doc_id, data)
                success += 1
            except Exception:
                try:
                    db.create_document(DATABASE, col_id, doc_id, data)
                    success += 1
                except Exception as e:
                    errors += 1
                    print(f"      ❌ {doc_id}: {e}")
            time.sleep(0.05)  # Rate limit
        print(f"      ✅ {success} succeeded, ❌ {errors} failed")


# ============================================================================
# MAIN
# ============================================================================

if __name__ == '__main__':
    if len(sys.argv) > 1:
        cmd = sys.argv[1]
        if cmd == '--push':
            push_to_appwrite()
        elif cmd == '--export':
            export_json()
        elif cmd == '--export-collections':
            export_per_collection()
        elif cmd == '--review':
            review_data()
        else:
            print(f"Unknown command: {cmd}")
            print("Usage: python3 appwrite_cloud_restore.py [--review|--export|--export-collections|--push]")
    else:
        review_data()
